from typing import List

def check(N: int, M: int, Edges: List[List[int]]) -> bool:
    def is_valid_path(path, v):
        if v in path:
            return False
        if len(path) > 1 and path[-1] not in adj[path[-2]]:
            return False
        return True

    def backtrack(path):
        if len(path) == N:
            return True
        for v in range(1, N + 1):
            if is_valid_path(path, v):
                path.append(v)
                if backtrack(path):
                    return True
                path.pop()
        return False

    adj = {i: set() for i in range(1, N + 1)}
    for u, v in Edges:
        adj[u].add(v)
        adj[v].add(u)

    for start in range(1, N + 1):
        if backtrack([start]):
            return True
    return False
